1	/* ===== Career Finder — feuille de style ===== */
2	:root {
3	  --bg: #f3f6f9; --surface: #ffffff; --surface-2: #f8fafc; --text: #0f172a; --muted: #64748b;
4	  --border: #e2e8f0; --primary: #0d9488; --primary-dark: #0f766e; --primary-soft: #ccfbf1;
5	  --accent: #f59e0b; --side: #0b1324; --side-text: #a8b3c7; --danger: #dc2626; --ok: #16a34a; --warn: #d97706;
6	  --radius: 14px; --radius-sm: 9px;
7	  --shadow: 0 1px 2px rgba(15,23,42,.06), 0 6px 20px rgba(15,23,42,.05);
8	  --shadow-lg: 0 12px 40px rgba(15,23,42,.18);
9	  --chip-l: 92%; --chip-text-l: 28%;
10	}
11	@media (prefers-color-scheme: dark) {
12	  :root {
13	    --bg: #0a1120; --surface: #111a2e; --surface-2: #0e1729; --text: #e6e9ef; --muted: #8fa0ba;
14	    --border: #1f2c47; --primary: #2dd4bf; --primary-dark: #5eead4; --primary-soft: #11403c;
15	    --side: #060b16; --shadow: 0 1px 2px rgba(0,0,0,.4), 0 6px 20px rgba(0,0,0,.25);
16	    --chip-l: 20%; --chip-text-l: 78%;
17	  }
18	}
19	* { box-sizing: border-box; }
20	html, body { margin: 0; height: 100%; }
21	body { font: 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
22	  background: var(--bg); color: var(--text); -webkit-font-smoothing: antialiased; }
23	[hidden] { display: none !important; }
24	h1 { font-size: 1.6rem; letter-spacing: -.02em; margin: 0 0 .25rem; line-height: 1.2; }
25	h2 { font-size: 1.05rem; margin: 0 0 .6rem; line-height: 1.3; }
26	h3 { font-size: 1rem; margin: 0 0 .4rem; }
27	p { margin: 0 0 .75rem; }
28	a { color: var(--primary-dark); text-underline-offset: 2px; }
29	code { background: var(--surface-2); border: 1px solid var(--border); padding: .05rem .35rem; border-radius: 6px; font-size: .85em; }
30	.muted { color: var(--muted); }
31	.error { color: var(--danger); font-size: .9rem; margin: .25rem 0 .5rem; }
32	.skip-link { position: absolute; left: -999px; top: 0; background: var(--primary); color: #fff; padding: .5rem .9rem; z-index: 200; border-radius: 0 0 8px 0; }
33	.skip-link:focus { left: 0; }
34	.ico { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex: none; }
35	
36	/* ---------- Formulaires & boutons ---------- */
37	label { display: block; font-size: .83rem; font-weight: 600; margin-bottom: .8rem; color: var(--text); }
38	input, select, textarea { width: 100%; margin-top: .3rem; padding: .58rem .75rem; font: inherit; font-weight: 400; color: inherit;
39	  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-sm); transition: border-color .15s, box-shadow .15s; }
40	input:hover, select:hover, textarea:hover { border-color: var(--muted); }
41	input:focus, select:focus, textarea:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 25%, transparent); }
42	button:focus-visible, a:focus-visible, .icon-btn:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; border-radius: 6px; }
43	textarea { resize: vertical; min-height: 84px; }
44	input[type=checkbox] { width: auto; margin: 0 .5rem 0 0; accent-color: var(--primary); }
45	input[type=range] { padding: 0; accent-color: var(--primary); }
46	input[type=file] { padding: .45rem; background: var(--surface-2); }
47	label.inline { display: flex; align-items: center; font-weight: 500; }
48	
49	.btn { display: inline-flex; align-items: center; justify-content: center; gap: .4rem; padding: .52rem .95rem; font: inherit; font-weight: 600;
50	  border: 1px solid var(--border); background: var(--surface); color: var(--text); border-radius: var(--radius-sm);
51	  cursor: pointer; text-decoration: none; transition: background .15s, border-color .15s, transform .05s, box-shadow .15s; }
52	.btn:hover { border-color: var(--primary); }
53	.btn:active { transform: translateY(1px); }
54	.btn.primary { background: var(--primary); border-color: var(--primary); color: #fff; box-shadow: 0 1px 2px rgba(13,148,136,.35); }
55	.btn.primary:hover { background: var(--primary-dark); border-color: var(--primary-dark); }
56	@media (prefers-color-scheme: dark) { .btn.primary { color: #042f2c; } }
57	.btn.danger { color: var(--danger); }
58	.btn.danger:hover { border-color: var(--danger); background: color-mix(in srgb, var(--danger) 8%, transparent); }
59	.btn.ghost { background: transparent; }
60	.btn.small { padding: .28rem .6rem; font-size: .8rem; }
61	.btn.block { width: 100%; }
62	.btn[disabled] { opacity: .45; cursor: not-allowed; transform: none; }
63	.icon-btn { display: inline-grid; place-items: center; width: 40px; height: 40px; border: 0; background: transparent; color: inherit; border-radius: 10px; cursor: pointer; }
64	.icon-btn:hover { background: var(--surface-2); }
65	
66	/* ---------- Authentification ---------- */
67	.auth { min-height: 100%; display: grid; place-items: center; padding: 1rem;
68	  background: radial-gradient(1200px 600px at 10% -10%, #115e59 0%, transparent 60%), linear-gradient(135deg, #0b1324, #0f3d3a); }
69	.auth-card { width: min(430px, 100%); background: var(--surface); border-radius: 20px; padding: 1.9rem; box-shadow: var(--shadow-lg); }
70	.auth-brand { display: flex; align-items: center; gap: .9rem; margin-bottom: .9rem; }
71	.auth-brand h1 { margin: 0; }
72	.auth-brand p { margin: 0; }
73	.tabs { display: flex; gap: .25rem; margin: 1.1rem 0; background: var(--bg); padding: .25rem; border-radius: 11px; }
74	.tab { flex: 1; padding: .5rem; border: 0; background: transparent; font: inherit; font-weight: 600; color: var(--muted); border-radius: 8px; cursor: pointer; }
75	.tab.active { background: var(--surface); color: var(--text); box-shadow: var(--shadow); }
76	
77	/* ---------- Mise en page ---------- */
78	.layout { display: grid; grid-template-columns: 252px 1fr; min-height: 100vh; }
79	.topbar, .scrim { display: none; }
80	.sidebar { background: var(--side); color: var(--side-text); display: flex; flex-direction: column; padding: 1.1rem .8rem;
81	  position: sticky; top: 0; height: 100vh; overflow-y: auto; }
82	.brand { display: flex; align-items: center; gap: .7rem; padding: .2rem .5rem 1.1rem; color: #fff; text-decoration: none; }
83	.brand strong { display: block; font-size: 1.05rem; letter-spacing: -.01em; }
84	.brand small { display: block; color: var(--side-text); font-size: .72rem; }
85	#nav { display: flex; flex-direction: column; gap: .12rem; flex: 1; }
86	.nav-title { margin: 1.1rem .7rem .3rem; font-size: .68rem; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: #5f6d86; }
87	#nav a { display: flex; align-items: center; gap: .65rem; color: var(--side-text); text-decoration: none; padding: .55rem .75rem; border-radius: 10px; transition: background .15s, color .15s; }
88	#nav a:hover { background: rgba(255,255,255,.07); color: #fff; }
89	#nav a.active { background: var(--primary); color: #fff; font-weight: 600; box-shadow: 0 2px 10px rgba(13,148,136,.35); }
90	@media (prefers-color-scheme: dark) { #nav a.active { color: #042f2c; } }
91	.userbox { border-top: 1px solid rgba(255,255,255,.1); padding: .9rem .4rem 0; margin-top: .8rem; display: grid; gap: .6rem; font-size: .9rem; color: #fff; }
92	.userline { display: flex; align-items: center; gap: .6rem; }
93	.userline .chip { margin-left: .4rem; }
94	.avatar { width: 34px; height: 34px; border-radius: 50%; display: inline-grid; place-items: center; background: linear-gradient(135deg, #14b8a6, #0f766e); color: #fff; font-weight: 700; }
95	.userbox .btn { color: var(--side-text); border-color: rgba(255,255,255,.18); }
96	.userbox .btn:hover { color: #fff; }
97	main { padding: 1.7rem 2.2rem 3.5rem; min-width: 0; max-width: 1400px; width: 100%; animation: fade .2s ease-out; }
98	@keyframes fade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
99	.page-head { display: flex; flex-wrap: wrap; gap: .75rem 1rem; align-items: flex-end; justify-content: space-between; margin-bottom: 1.3rem; }
100	.page-head p { margin: 0; color: var(--muted); }
101	.section-title { margin: 1.6rem 0 .7rem; }
102	
103	/* ---------- Composants ---------- */
104	.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1.15rem; box-shadow: var(--shadow); }
105	.card.flat { box-shadow: none; background: var(--surface-2); }
106	.grid { display: grid; gap: 1rem; }
107	.grid.stats { grid-template-columns: repeat(auto-fit, minmax(175px, 1fr)); }
108	.grid.cards { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); }
109	.grid.two { grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr)); }
110	.stat { display: flex; align-items: center; gap: .9rem; }
111	.stat .bubble { width: 46px; height: 46px; border-radius: 13px; display: grid; place-items: center; font-size: 1.3rem; background: var(--primary-soft); flex: none; }
112	.stat .num { font-size: 1.7rem; font-weight: 800; line-height: 1.05; letter-spacing: -.02em; }
113	.stat .lbl { color: var(--muted); font-size: .82rem; }
114	.toolbar { display: flex; flex-wrap: wrap; gap: .8rem; align-items: end; margin-bottom: 1rem; }
115	.toolbar > * { flex: 1 1 170px; margin: 0; }
116	.toolbar .btn { flex: 0 0 auto; }
117	
118	.chip { display: inline-block; padding: .1rem .6rem; border-radius: 999px; font-size: .74rem; font-weight: 600; background: var(--primary-soft); color: var(--primary-dark); white-space: nowrap; }
119	.chip.gray { background: var(--surface-2); color: var(--muted); border: 1px solid var(--border); }
120	.chip.ok { background: #dcfce7; color: #166534; }
121	.chip.warn { background: #fef3c7; color: #92400e; }
122	.chip.default { background: var(--accent); color: #3b2300; }
123	@media (prefers-color-scheme: dark) { .chip.ok { background: #14532d; color: #bbf7d0; } .chip.warn { background: #4a2f05; color: #fde68a; } }
124	/* couleur par secteur */
125	.chip[data-sector] { background: hsl(var(--h, 215) 70% var(--chip-l)); color: hsl(var(--h, 215) 55% var(--chip-text-l)); }
126	.chip[data-sector="Informatique"] { --h: 172; } .chip[data-sector="Hôtellerie"] { --h: 24; }
127	.chip[data-sector="Tourisme"] { --h: 200; }     .chip[data-sector="Construction"] { --h: 38; }
128	.chip[data-sector="Comptabilité"] { --h: 262; } .chip[data-sector="Industrie"] { --h: 215; }
129	.chip[data-sector="Logistique"] { --h: 148; }   .chip[data-sector="Marketing"] { --h: 322; }
130	.chip[data-sector="RH"] { --h: 345; }           .chip[data-sector="Commerce"] { --h: 88; }
131	.chip[data-sector="Autre"] { background: var(--surface-2); color: var(--muted); border: 1px solid var(--border); }
132	
133	.score { display: inline-flex; align-items: center; gap: .45rem; font-weight: 700; font-variant-numeric: tabular-nums; }
134	.bar { width: 58px; height: 6px; background: var(--border); border-radius: 3px; overflow: hidden; }
135	.bar > i { display: block; height: 100%; background: var(--primary); border-radius: 3px; }
136	.score.hi .bar > i { background: var(--ok); } .score.mid .bar > i { background: var(--accent); } .score.lo .bar > i { background: var(--danger); }
137	
138	.table-wrap { overflow-x: auto; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); }
139	table { width: 100%; border-collapse: collapse; font-size: .9rem; }
140	th { position: sticky; top: 0; background: var(--surface-2); text-align: left; font-size: .72rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); padding: .75rem .8rem; border-bottom: 1px solid var(--border); white-space: nowrap; }
141	td { padding: .7rem .8rem; border-bottom: 1px solid var(--border); vertical-align: top; }
142	tbody tr { transition: background .12s; }
143	tbody tr:hover { background: var(--surface-2); }
144	tr:last-child td { border-bottom: 0; }
145	td .sub, .sub { color: var(--muted); font-size: .8rem; }
146	.actions { display: flex; flex-wrap: wrap; gap: .35rem; }
147	.star { background: none; border: 0; cursor: pointer; font-size: 1.25rem; line-height: 1; padding: .1rem; color: var(--border); transition: transform .12s, color .12s; }
148	.star:hover { transform: scale(1.2); color: var(--accent); }
149	.star.on { color: var(--accent); }
150	
151	.empty { text-align: center; padding: 2.8rem 1rem; color: var(--muted); }
152	.empty .big { font-size: 2.2rem; display: block; margin-bottom: .4rem; }
153	.notice { padding: .8rem 1rem; border-radius: 11px; background: #fef3c7; color: #92400e; margin-bottom: 1rem; font-size: .9rem; }
154	.notice.info { background: var(--primary-soft); color: var(--primary-dark); }
155	@media (prefers-color-scheme: dark) { .notice { background: #3a2a07; color: #fde68a; } }
156	.report { background: var(--surface-2); border: 1px solid var(--border); border-radius: 10px; padding: .65rem .85rem; font-size: .85rem; margin-top: .75rem; }
157	
158	/* squelettes de chargement */
159	.skeleton { display: grid; gap: 1rem; }
160	.sk { height: 18px; border-radius: 8px; background: linear-gradient(90deg, var(--border) 25%, var(--surface-2) 50%, var(--border) 75%); background-size: 200% 100%; animation: shimmer 1.3s infinite linear; }
161	.sk.title { width: 40%; height: 28px; } .sk.block { height: 90px; border-radius: var(--radius); }
162	@keyframes shimmer { to { background-position: -200% 0; } }
163	
164	/* offres */
165	.offer { display: flex; flex-direction: column; }
166	.offer h3 { font-size: 1.02rem; }
167	.offer dl { margin: .5rem 0; display: grid; grid-template-columns: auto 1fr; gap: .25rem .75rem; font-size: .87rem; }
168	.offer dt { color: var(--muted); } .offer dd { margin: 0; }
169	.offer .actions { margin-top: auto; padding-top: .6rem; }
170	
171	/* kanban */
172	.kanban { display: grid; grid-template-columns: repeat(auto-fit, minmax(215px, 1fr)); gap: .9rem; align-items: start; }
173	.col { background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius); padding: .8rem; min-height: 120px; }
