def _read_pdf_upload(upload: UploadFile) -> bytes:
    """Lit un PDF téléversé (5 Mo max) et vérifie extension + signature."""
    data = upload.file.read(MAX_CV_BYTES + 1)
    if len(data) > MAX_CV_BYTES:
        raise HTTPException(status_code=413, detail="CV trop volumineux (5 Mo maximum).")
    if not (upload.filename or "").lower().endswith(".pdf") or not data.startswith(b"%PDF"):
        raise HTTPException(status_code=422, detail="Le CV doit être un fichier PDF valide.")
    return data


