  const essentialVariables = [
    '--primary-500',
    '--gray-900',
    '--shadow-md',
    '--radius-md'
  ];

  const mainCSSPath = path.join(cssPath, 'main.css');
  if (!fs.existsSync(mainCSSPath)) {
