424	let mapsPromise = null;
425	function loadGoogleMaps(key) {
426	  if (window.google && window.google.maps) return Promise.resolve();
427	  if (mapsPromise) return mapsPromise;
428	  mapsPromise = new Promise((resolve, reject) => {
429	    window.__mapsReady = resolve;
430	    window.gm_authFailure = () => toast("Clé Google Maps refusée : vérifie-la dans la console Google Cloud.", "error");
431	    const s = document.createElement("script");
432	    s.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&callback=__mapsReady`;
433	    s.async = true;
434	    s.onerror = () => { mapsPromise = null; reject(new Error("Impossible de charger Google Maps.")); };
435	    document.head.appendChild(s);
436	  });
437	  return mapsPromise;
438	}
