447	      <span id="m-count" class="muted"></span>
448	    </div>
449	    <div id="map-msg"></div><div id="map"></div>`;
450	
451	  let key = sessionStorage.getItem("cf_gmaps_key") || "";
452	  try { if (!key) key = (await api("/maps-key")).api_key || ""; } catch { /* géré ci-dessous */ }
453	  if (!key) {
454	    $("#map").hidden = true;
455	    $("#map-msg").innerHTML = `<div class="notice">Aucune clé Google Maps. Renseigne <code>GOOGLE_MAPS_API_KEY</code> dans
456	      le fichier <code>.env</code> du serveur, ou saisis une clé pour cette session dans
457	      <a href="#/donnees">Collecte &amp; Import</a>.</div>`;
458	    return;
459	  }
460	  try { await loadGoogleMaps(key); } catch (e) { $("#map-msg").innerHTML = `<div class="notice">${esc(e.message)}</div>`; return; }
461	
462	  const map = new google.maps.Map($("#map"), { center: { lat: 31.6295, lng: -7.9811 }, zoom: 12 });
463	  const info = new google.maps.InfoWindow();
464	  let markers = [];
465	
466	  const draw = () => {
467	    markers.forEach((m) => m.setMap(null)); markers = [];
468	    const sec = $("#m-secteur").value, min = Number($("#m-score").value);
469	    $("#m-score-val").textContent = min;
