471	      && (!sec || o.secteur === sec) && (o.score_opportunite || 0) >= min);
472	    const bounds = new google.maps.LatLngBounds();
473	    pts.forEach((o) => {
474	      const pos = { lat: o.latitude, lng: o.longitude };
475	      const m = new google.maps.Marker({ position: pos, map, title: o.nom });
476	      m.addListener("click", () => {
477	        const site = safeUrl(o.site_web);
478	        info.setContent(`<div style="max-width:220px;color:#0f172a"><strong>${esc(o.nom)}</strong><br>
