480	          ${o.email ? `<br>✉️ ${esc(o.email)}` : ""}
481	          ${site ? `<br><a href="${esc(site)}" target="_blank" rel="noopener noreferrer">Site web</a>` : ""}</div>`);
482	        info.open(map, m);
483	      });
484	      markers.push(m); bounds.extend(pos);
485	    });
486	    $("#m-count").textContent = `${pts.length} entreprise(s) affichée(s)`;
487	    if (pts.length > 1) map.fitBounds(bounds);
488	  };
489	  $("#m-secteur").addEventListener("change", draw);
490	  $("#m-score").addEventListener("input", draw);
491	  draw();
492	};
