### **3️⃣ deploy-interface.ps1 (Script de déploiement principal)**

```powershell
# deploy-interface.ps1
# Script de déploiement principal pour Windows PowerShell

# Fonction pour exécuter les scripts PowerShell
function Execute-PsScript {
    param([string]$ScriptPath)

    if (Test-Path $ScriptPath) {
        Write-Host "Exécution de $ScriptPath..."
        & $ScriptPath
        $lastExitCode = $LASTEXITCODE
        if ($lastExitCode -ne 0) {
            Write-Error "Script $ScriptPath a échoué avec le code d'erreur : $lastExitCode"
            return $false
        } else {
            Write-Success "$ScriptPath terminé avec succès"
            return $true
        }
    } else {
        Write-Error "Script $ScriptPath non trouvé"
        return $false
    }
}

# Fonction pour construire l'application dans Docker (si Docker est disponible)
function Build-With-Docker {
    Write-Host "🐳 Déploiement avec Docker..."

    if (Get-Command docker -ErrorAction SilentlyContinue) {
        try {
            # Construire les images Docker
            docker build -t career-finder-backend ./backend
            docker build -t career-finder-frontend ./frontend

            # Démarrer les services
            docker-compose up -d --build

            Write-Success "Docker DockerCompose démarré avec succès"
            return $true
        } catch {
            Write-Error "Erreur lors du déploiement Docker : $($_.Exception.Message)"
            return $false
        }
    } else {
        Write-Warning "Docker non trouvé - passage au déploiement local"
        return $false
    }
}

# Fonction principale de déploiement
function Main-Deploy {
    Write-Host "🚀 Démarrage du déploiement de Career Finder Marrakech"
    Write-Host ""

    # Exécuter les scripts de validation et de tests
    $scripts = @(
        "./scripts/validate-structure.ps1"
        "./scripts/test-frontend-structure.ps1"
        "./scripts/test-ui-components.ps1"
    )

    $allSuccess = $true
    foreach ($script in $scripts) {
        Write-Host "Exécution de $script..."
        if (-not (Execute-PsScript $script)) {
            $allSuccess = $false
        }
    }

    if (-not $allSuccess) {
        Write-Error "Certains scripts de validation ont échoué. Veuillez corriger les erreurs avant de continuer."
        return
    }

    # Tenter le déploiement avec Docker en premier
    if (Get-Command docker -ErrorAction SilentlyContinue) {
        Write-Host "🐳 Tentative de déploiement avec Docker..."
        if (Build-With-Docker) {
            Write-Success "Déploiement Docker réussi !"
            return
        } else {
            Write-Warning "Déploiement Docker échoué - tentative de déploiement local"
        }
    }

    # Si Docker n'est pas disponible ou échoue, déployer localement
    Write-Host "🖥️ Tentative de déploiement local..."

    # Vérifier la configuration Python
    if (-not (Get-Command python3 -ErrorAction SilentlyContinue)) {
        Write-Error "Python3 non trouvé. Veuillez installer Python 3.8+ depuis https://www.python.org/downloads/windows/"
        return
    }

    # Installer les dépendances
    Write-Host "📦 Installation des dépendances Python..."
    try {
        pip3 install -r requirements.txt
        pip3 install -r backend/requirements.txt
        Write-Success "Dépendances Python installées"
    } catch {
        Write-Error "Erreur lors de l'installation des dépendances : $($_.Exception.Message)"
        return
    }

    # Exécuter le backend
    Write-Host "🐍 Démarrage du backend FastAPI..."
    try {
        Start-Job -FilePath "./backend/main.py" -ArgumentList @("uvicorn", "main:app", "--host", "0.0.0.0", "--port", "8000", "--reload") -PasInterception:$false
        Write-Success "Backend FastAPI démarré sur http://localhost:8000"
    } catch {
        Write-Error "Erreur lors du démarrage du backend : $($_.Exception.Message)"
        return
    }

    Write-Host ""
    Write-Host "🎉 Déploiement terminé !"
    Write-Host ""
    Write-Host "📋 Services démarrés :"
    Write-Host "   🐍 FastAPI Backend : http://localhost:8000"
    Write-Host "   🌐 Interface utilisateur : http://localhost:8000/"
    Write-Host ""
    Write-Host "💡 Pour arrêter tous les services :"
    Write-Host "   Stop-Powershell"
}

# Exécuter le déploiement
Main-Deploy
```

